39|static ZSTD_inBuffer makeInBuffer(const uint8_t **src, size_t *size)
40|{
41|  ZSTD_inBuffer buffer = { *src, 0, 0 };
42|
43|  FUZZ_ASSERT(*size > 0);
44|  buffer.size = (FUZZ_rand(&seed) % *size) + 1;
45|  FUZZ_ASSERT(buffer.size <= *size);
46|  *src += buffer.size;
47|  *size -= buffer.size;
48|
49|  return buffer;
50|}
