52|int LLVMFuzzerTestOneInput(const uint8_t *src, size_t size)
53|{
54|    seed = FUZZ_seed(&src, &size);
55|
56|    /* Allocate all buffers and contexts if not already allocated */
57|    if (!buf) {
58|      buf = malloc(kBufSize);
59|      FUZZ_ASSERT(buf);
60|    }
61|
62|    if (!dstream) {
63|        dstream = ZSTD_createDStream();
64|        FUZZ_ASSERT(dstream);
65|        FUZZ_ASSERT(!ZSTD_isError(ZSTD_initDStream(dstream)));
66|    } else {
67|        FUZZ_ASSERT(!ZSTD_isError(ZSTD_resetDStream(dstream)));
68|    }
69|
70|    while (size > 0) {
71|        ZSTD_inBuffer in = makeInBuffer(&src, &size);
72|        while (in.pos != in.size) {
73|            ZSTD_outBuffer out = makeOutBuffer();
74|            size_t const rc = ZSTD_decompressStream(dstream, &out, &in);
75|            if (ZSTD_isError(rc)) goto error;
76|            if (rc == 0) FUZZ_ASSERT(!ZSTD_isError(ZSTD_resetDStream(dstream)));
77|        }
78|    }
79|
80|error:
81|#ifndef STATEFUL_FUZZING
82|    ZSTD_freeDStream(dstream); dstream = NULL;
83|#endif
84|    return 0;
85|}

1939|static size_t ZSTD_decompress_insertDictionary(ZSTD_DCtx* dctx, const void* dict, size_t dictSize)
1940|{
1941|    if (dictSize < 8) return ZSTD_refDictContent(dctx, dict, dictSize);
1942|    {   U32 const magic = MEM_readLE32(dict);
1943|        if (magic != ZSTD_MAGIC_DICTIONARY) {
1944|            return ZSTD_refDictContent(dctx, dict, dictSize);   /* pure content mode */
1945|    }   }
1946|    dctx->dictID = MEM_readLE32((const char*)dict + 4);
1947|
1948|    /* load entropy tables */
1949|    {   size_t const eSize = ZSTD_loadEntropy(&dctx->entropy, dict, dictSize);
1950|        if (ZSTD_isError(eSize)) return ERROR(dictionary_corrupted);
1951|        dict = (const char*)dict + eSize;
1952|        dictSize -= eSize;
1953|    }
1954|    dctx->litEntropy = dctx->fseEntropy = 1;
1955|
1956|    /* reference dictionary content */
1957|    return ZSTD_refDictContent(dctx, dict, dictSize);
1958|}

